// static
bool StructTraits<::nearby_share::mojom::ContactRecord::DataView, ::nearby_share::mojom::ContactRecordPtr>::Read(
    ::nearby_share::mojom::ContactRecord::DataView input,
    ::nearby_share::mojom::ContactRecordPtr* output) {
  bool success = true;
  ::nearby_share::mojom::ContactRecordPtr result(::nearby_share::mojom::ContactRecord::New());
  
      if (success && !input.ReadId(&result->id))
        success = false;
      if (success && !input.ReadPersonName(&result->person_name))
        success = false;
      if (success && !input.ReadImageUrl(&result->image_url))
        success = false;
      if (success && !input.ReadIdentifiers(&result->identifiers))
        success = false;
  *output = std::move(result);
  return success;
}

// static
bool UnionTraits<::nearby_share::mojom::ContactIdentifier::DataView, ::nearby_share::mojom::ContactIdentifierPtr>::Read(
    ::nearby_share::mojom::ContactIdentifier::DataView input,
    ::nearby_share::mojom::ContactIdentifierPtr* output) {
  using UnionType = ::nearby_share::mojom::ContactIdentifier;
  using Tag = UnionType::Tag;

  switch (input.tag()) {
    case Tag::kObfuscatedGaia: {
      std::string result_obfuscated_gaia;
      if (!input.ReadObfuscatedGaia(&result_obfuscated_gaia))
        return false;

      *output = UnionType::NewObfuscatedGaia(
          std::move(result_obfuscated_gaia));
      break;
    }
    case Tag::kPhoneNumber: {
      std::string result_phone_number;
      if (!input.ReadPhoneNumber(&result_phone_number))
        return false;

      *output = UnionType::NewPhoneNumber(
          std::move(result_phone_number));
      break;
    }
    case Tag::kAccountName: {
      std::string result_account_name;
      if (!input.ReadAccountName(&result_account_name))
        return false;

      *output = UnionType::NewAccountName(
          std::move(result_account_name));
      break;
    }
    default:

      return false;
  }
  return true;
}

